import XCTest

@testable import OrbitDropHelperCore

/// Math.atan2 / Math.hypot ports must reproduce V8's results bit for bit
/// (vectors and digest generated by scripts/gen-fixtures.mjs with Node).
final class JSMathTests: XCTestCase {
  private func load() throws -> [String: Any] {
    try TestPaths.json(TestPaths.fixture("js-math-vectors.json")) as! [String: Any]
  }

  func testRowsMatchV8BitForBit() throws {
    let rows = try load()["rows"] as! [[String]]
    XCTAssertGreaterThan(rows.count, 2000)
    var atanMismatches: [String] = []
    var hypotMismatches: [String] = []
    for row in rows {
      let y = double(fromBits: row[0])
      let x = double(fromBits: row[1])
      let atan = JSMath.atan2(y, x)
      let hyp = JSMath.hypot(x, y)
      // NaN results compare by NaN-ness (payload bits are not specified by JS).
      let expectedAtan = double(fromBits: row[2])
      let expectedHypot = double(fromBits: row[3])
      if !(atan.bitPattern == expectedAtan.bitPattern || (atan.isNaN && expectedAtan.isNaN)) {
        atanMismatches.append("atan2(\(y), \(x)) = \(atan) expected \(expectedAtan)")
      }
      if !(hyp.bitPattern == expectedHypot.bitPattern || (hyp.isNaN && expectedHypot.isNaN)) {
        hypotMismatches.append("hypot(\(x), \(y)) = \(hyp) expected \(expectedHypot)")
      }
    }
    XCTAssertEqual(atanMismatches.count, 0, atanMismatches.prefix(5).joined(separator: "\n"))
    XCTAssertEqual(hypotMismatches.count, 0, hypotMismatches.prefix(5).joined(separator: "\n"))
  }

  /// 200 000 generated inputs, compared through an FNV-1a digest of the result bits.
  func testDigestOverGeneratedInputs() throws {
    let digest = try load()["digest"] as! [String: Any]
    var state = UInt32(digest["seed"] as! Int)
    let count = digest["count"] as! Int
    func next() -> UInt32 {
      state ^= state << 13
      state ^= state >> 17
      state ^= state << 5
      return state
    }
    func fnv(_ h: UInt32, _ x: Double) -> UInt32 {
      var h = h
      var b = x.bitPattern
      for _ in 0..<8 {
        h ^= UInt32(b & 0xFF)
        h = h &* 16_777_619
        b >>= 8
      }
      return h
    }
    var hAtan: UInt32 = 2_166_136_261
    var hHypot: UInt32 = 2_166_136_261
    for _ in 0..<count {
      let a = Double(next()) / 4_294_967_296
      let b = Double(next()) / 4_294_967_296
      let y = (a - 0.5) * 1000
      let x = (b - 0.5) * 1000
      hAtan = fnv(hAtan, JSMath.atan2(y, x))
      hHypot = fnv(hHypot, JSMath.hypot(x, y))
    }
    XCTAssertEqual(Int(hAtan), digest["atan2"] as? Int, "atan2 digest differs from V8")
    XCTAssertEqual(Int(hHypot), digest["hypot"] as? Int, "hypot digest differs from V8")
  }

  /// Documents why the ports exist: the system libm disagrees with V8 on many inputs.
  func testSystemLibmWouldNotBeBitExact() throws {
    let rows = try load()["rows"] as! [[String]]
    var libmHypotDiffers = 0
    for row in rows.prefix(2000) {
      let y = double(fromBits: row[0])
      let x = double(fromBits: row[1])
      if Foundation.hypot(x, y).bitPattern != double(fromBits: row[3]).bitPattern { libmHypotDiffers += 1 }
    }
    XCTAssertGreaterThan(libmHypotDiffers, 0)
  }

  func testJSHelpers() {
    XCTAssertEqual(JSMath.remainder(-370, 360), -10)
    XCTAssertEqual(JSMath.remainder(725, 360), 5)
    XCTAssertEqual(JSMath.trunc(-2.7), -2)
    XCTAssertEqual(JSMath.floor(-2.5), -3)
    XCTAssertEqual(JSMath.min(-0.0, 0.0).sign, .minus)
    XCTAssertEqual(JSMath.max(-0.0, 0.0).sign, .plus)
    XCTAssertTrue(JSMath.min(.nan, 1).isNaN)
    XCTAssertEqual(Coords.roundHalfUp(-2.5), -2)
    XCTAssertEqual(Coords.roundHalfUp(2.5), 3)
  }
}
